    "standardName": "CSA O15",
    "edition": "2015 (R2020)",
    "clauseNumber": "6.6.2",
    "title": "Treated pole surface protection",
    "section": "6 Quality of work and finish, markings, handling, storage, and inspection",
    "page": 24,
    "text": "Cant hooks, pole tongs, or other tools shall not be applied to the groundline section of any pole.",
    "tablesReferenced": [],
